internal object DuaMaiDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_breaking_fast" to DuaText("उपवास तोड़य पर", "प्यास खतम भऽ गेल अछि, नससभ नम भऽ गेल अछि, आ यदि अल्लाह चाहैत छथि तँ पुरस्कार पक्का भऽ गेल अछि।", "इफ्तारक समय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम अपना व्रत तोड़ैत काल ई कहलनि।"),
        "dua_new_clothes" to DuaText("नव कपड़ा पहिरनाय", "ऐ अल्लाह, सब प्रशंसा अहाँक अछि, अहाँ हमरा ई वस्त्र पहिरलहुँ। हम अहाँ सँ एकर नीक आ नीक काजक प्रार्थना करैत छी, आ एकर अधलाह आ अधलाह काज सँ अहाँ सँ शरण माँगैत छी।", "नव वस्त्र पहिरने समय (एकर नामकरण, जेना कि कमीज या पगड़ी)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम नव वस्त्र पहिरने काल ई दुआ बनौलनि। (परिधानक लेल दैनिक दुआ'परिधान करब'क अन्तर्गत अछि।)"),
        "dua_rabbana_atina" to DuaText("संसार आ आख़िरत मे नीक", "हे हमर प्रभु, हमरा सभ केँ एहि संसार मे भलाइ आ आख़िरत मे भलाइ प्रदान करू आ आगि के सजा सँ बचाउ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम बहुधा दुआ करैत छलाह।", "एक दुआ जे संसार आ आखिरतक सब नीक काजकेँ एकत्रित करैत अछि।"),
        "dua_rabbi_zidni_ilma" to DuaText("ज्ञानमे वृद्धि", "हे हमर प्रभु, हमरा ज्ञान मे वृद्धि करू।", "ज्ञानमे वृद्धि लेल।", "अल्लाह पैगम्बर सल्लल्लाहु अलैहि वसल्लम केँ आदेश देलनि जे ओ ज्ञानक अतिरिक्त किछु नहि माँगनि।"),
        "dua_musa_sharh_sadr" to DuaText("छातीक उद्घाटन (मूसा एएस)", "हे हमर प्रभु, हमर लेल हमर छाती बढ़ाउ, हमर काजकेँ सरल बनाउ आ हमर जिब्रोसँ गाँठ खोलू जाहि सँ ओ सभ हमर बात बुझथि।", "कोनो परीक्षा सँ पहिने, भाषण या कोनो कठिन कार्य।", "पैगम्बर मूसा (अ. स.) क दुआ-हृदयक शांति आ अपन काजमे सहजता।"),
        "dua_la_tuzigh" to DuaText("हृदयक स्थिरता", "हमर प्रभु, हमरा सभक मार्ग देखाबऽ पर हमरा सभक हृदय नहि भटकि, आ हमरा सभ पर अपना द्वारा दया करू। निश्चय ही अहाँ सभ दाता छी।", "मार्गदर्शन पर स्थिरताक लेल।", "विश्वासमे अटल रहबाक लेल दुआ।"),
        "dua_ya_muqallib" to DuaText("ओ टर्नर ऑफ हार्ट्स", "ओ हृदयक परिवर्तक, हमर हृदय अपन धर्म पर अटल राखू।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम बहुधा ई दुआ बनौलनि।", "उम्म सलामाह (रा.) क अनुसार पैगम्बर सल्लल्लाहु अलैहि वसल्लम बहुधा दुआ करैत छलाह।"),
        "dua_la_tuakhidhna" to DuaText("सूरह अल-बकाराक अन्तिम आयतसभ", "ऐ हमर प्रभु, जँ हम सभ भुलैत छी अथवा कोनो गलती करैत छी तँ हमरा सभ पर दोष नहि लगाबय। ऐ हमर प्रभु, हमरा सभ पर एहन बोझ नहि लगाउ जे अहाँ हमरा सभ पर पहिनेक लोक सभ पर लगौलनि। ऐ हमर प्रभु, हमरा सभ पर एहन बोझ नहि लगाउ जे हम सभ पर नहि पड़ सकैत अछि। हमरा सभ पर क्षमा कऽ दियौक, हमरा सभ पर क्षमा कऽ दियौक आ हमरा सभ पर दया करी। अहाँ सभ हमर रक्षक छी, तेँ इनकार करय वला लोक सभ सँ हमरा सभ पर सहायता करू।", "राति मे सोय सँ पहिने-सूरह अल-बकारहक अन्तिम दू श्लोक।", "जे केओ राति मे सूरह अल-बकारहक अन्तिम दू आयत के पाठ करत, ओ सब हुनका लेल पर्याप्त होयत।"),
        "dua_visiting_sick" to DuaText("बीमारकेँ भेँट करब", "हम प्रबल सिंहासनक स्वामी, शक्तिशाली अल्लाह सँ प्रार्थना करैत छी जे ओ अहाँ सभ केँ ठीक करी।", "सात बेर जखन रोगीसँ भेंट कयल जाइत हो।", "जँ मृत्युक समय नहि आयल अछि तँ अल्लाह ओकरा ठीक कऽ देत।"),
        "dua_ruqyah_pain" to DuaText("शारीरिक दर्दक लेल", "हम जे किछु अनुभव करैत छी आ जाहि सँ डरैत छी, तकरा अधलाह व्यवहार सँ अल्लाह आ हुनकर शक्ति मे शरण चाहैत छी।", "अपन हाथकेँ ओहि ठाम राखू जतय दर्द होइत अछि, तीन बेर बिस्मिल्लाह, फेर सात बेर ई दुआ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम उथमान इब्न अबिल -'अस (रा.) केँ दर्दक लेल ई सिखौलनि।"),
        "dua_ruqyah_nabawi" to DuaText("बीमारक लेल भविष्यसूचक रुकिया", "ऐ अल्लाह, मानवजाति के प्रभु! हानि केँ हटा दे आ इलाज करा दे, कारण अहाँ ही ठीक करैत छी; अहाँक इलाजक अतिरिक्त कोनो इलाज नहि अछि-एकटा इलाज जे कोनो बीमारी केँ छोड़ि नहि दैत अछि।", "जखन कि रोगी व्यक्ति पर हाथ राखल जाइत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम अपन परिवारक बीमार सदस्यसँ भेंट करैत काल ई पाठ कयलनि।"),
        "dua_kalimat_tammat" to DuaText("पूर्ण शब्दमे शरण प्राप्त करब", "हम अल्लाह के सिद्ध वचन मे शरण चाहैत छी जे ओ जे किछु उत्पन्न कयने छथि ओकर बुराई सँ बचैत अछि।", "जखन कोनो स्थान पर, वा साँझमे रुकैत छी।", "जे केओ कोनो स्थान पर रुकैत अछि आ ई कहैत अछि, ओकरा ओहि समय धरि कोनो हानि नहि पहुँचय जखन धरि ओ ओकरा नहि छोड़ि दैत अछि।"),
        "dua_evil_eye" to DuaText("बच्चासभक लेल सुरक्षा (दुष्ट नेत्र)", "हम अहाँ सभ केँ प्रत्येक शैतान आ प्रत्येक विषाक्त प्राणी सँ, आ प्रत्येक हानिकारक आँखि सँ, अल्लाह के पूर्ण शब्द मे, सुरक्षा चाहैत छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम हसन आ हुसैन (र.) पर ई पाठ कयलनि।", "बच्चाकेँ दुष्ट दृष्टि आ हानि सँ बचय लेल एक सुन्नत दुआ (एकटा बच्चाक लेल'उधुका'कहल जाइत अछि)।"),
        "dua_seeing_afflicted" to DuaText("कोनोकेँ मुकदमामे देखनाइ", "प्रशंसा अछि अल्लाह के जे हमरा ओहि सँ बचौलनि जकर संग ओ अहाँ सभ केँ परखल छथि, आ अपन सृष्टिक बेसी भाग पर हमरा पर कृपा कयलनि।", "कोनो व्यक्ति के मुकदमामे देखलाक बाद (चुपचाप स्वयं केँ कहि दियौक)।", "जे ई कहैत अछि जे ओ ओहि मुकदमासँ सुरक्षित अछि।"),
        "dua_istikhara" to DuaText("सलात अल-इस्तिखारा", "ऐ अल्लाह, हम अहाँक ज्ञानसँ नीक काज करैत छी, हम अहाँक शक्ति द्वारा क्षमता प्राप्त करैत छी, आ हम अहाँ सँ अहाँक महान अनुग्रह माँगैत छी। अहाँ लग शक्ति अछि आ हमरा लग कोनो नहि अछि। अहाँ जनैत छी आ हम नहि छी, आ अहाँ अदृश्यक जानकार छी। हे अल्लाह, यदि अहाँक ज्ञानमे ई बात (ध्यान मे आनि) हमर धर्म, हमर जीवन आ हमर अन्तक लेल नीक अछि, तँ हमरा लेल एकर आदेश दिअ, हमरा लेल ई सरल बनाउ आ हमरा एहि मे आशीर्वाद दिअ। आ यदि अहाँक ज्ञानमे ई मामला हमर धर्म, हमर जीवन आ हमर अन्तक लेल खराब अछि, तँ एकरा हमरा सँ दूर कऽ दियौक आ हमरा सँ दूर कऽ दियौक, आ हमरा लेल नीक काजक आदेश दियौक जतऽ धरि ई भऽ सकय, तकर संग हमरा सन्तुष्ट करू।", "स्वैच्छिक प्रार्थनाक दू राकतक बाद, कोनो अनुज्ञेय मामलामे सबसँ नीक ताकबाक लेल।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम साथीकेँ कुरानक एक सूरह सिखबैत हुनका सभ मामिलामे इस्तिकारा सिखौलनि।"),
        "dua_allahumma_bika_asbahna" to DuaText("अल्लाहुम्मा बीका अस्बाहना", "हे अल्लाह, हम सभ भोर मे अहाँक द्वारा प्रवेश करैत छी आ साँझ मे अहाँक द्वारा प्रवेश करैत छी; अहाँ सँ हम सभ जीवित छी आ अहाँ सँ मरि जाइत छी, आ अहाँक लेल पुनरुत्थान अछि।", "भोरमे।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम साथीगण केँ आइ भोर-साँझ ई कहबाक शिक्षा देलनि।"),
        "dua_allahumma_bika_amsayna" to DuaText("अल्लाहुम्मा बीका अम्सेना", "ऐ अल्लाह, हम सभ साँझ मे अहाँक द्वारा प्रवेश करैत छी आ भोर मे अहाँक द्वारा प्रवेश करैत छी; अहाँक द्वारा हम सभ जीवित छी आ अहाँक द्वारा मरि जाइत छी आ अहाँक दिस फिरब अछि।", "साँझमे।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम साथीगण केँ आइ भोर-साँझ ई कहबाक शिक्षा देलनि।"),
        "dua_afiyah_morning" to DuaText("अफियाह के माँगैत अछि", "ऐ अल्लाह, हम अहाँ सँ एहि संसार आ आख़िरत मे क्षमा आ कल्याणक प्रार्थना करैत छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एहि दुआ केँ कहियो नहि छोड़ि देलनि, सुबह वा साँझ।", "कल्याणसँ नीक कोनो चीज ककरो नहि देल गेल अछि।"),
        "dua_afini_fi_badani" to DuaText("शरीर, श्रवण आ दृष्टि के स्वास्थ्य", "ऐ अल्लाह, हमर शरीरक कल्याण करू। ऐ अल्लाह, हमर श्रवणक कल्याण करू। ऐ अल्लाह, हमर दृष्टि के कल्याण करू। अहाँक अतिरिक्त कोनो देवता नहि अछि।", "तीन बेर प्रतिदिन भोर आ साँझ।", "स्वास्थ्य आ इन्द्रियसभक सुरक्षाक लेल एक दुआ।"),
        "dua_ya_hayyu_aslih" to DuaText("हमर सभ मामला ठीक करू।", "हे सदा जीवित, हे पालनकर्ता, हम अहाँक दयासँ सहायता चाहैत छी, हमर सभ काज ठीक कऽ दियौक आ पलक झपकय तक हमरा अपन पर नहि छोड़ि दियौक।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम फातिमा (र) केँ सुबह-साँझ ई कहबाक सलाह देलनि।", "हर मामलामे अल्लाहसँ मदद माँगैत छी।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("जुवेरिया के तसबीह (आर. ए.)", "महिमावान अछि अल्लाह आ समस्त प्रशंसा हुनकर अछि-हुनकर सृजन, ओना हुनका प्रसन्न करैत अछि, हुनकर सिंहासनक भार आ हुनकर वचनक स्याहीक बराबर।", "भोरमे तीन बेर-घण्टाक धिक्रसँ बेसी भारी।", "भोरसँ मध्य भोर धरि एहि चारि वाक्यांशकेँ तीन बेर कहने सँ धिक्र बेसी होइत अछि।"),
        "dua_salawat" to DuaText("दुरूद-ए-इब्राहिमी", "ऐ अल्लाह, मुहम्मद सल्लल्लाहु अलैहि वसल्लम आ मुहम्दक परिवार पर नमाज़ पठाउ जेना अहाँ इब्राहिम (अ. स.) आ इब्राहिमक परिवार पर नमाज़ पठौलनि; अहाँ प्रशंसनीय, महिमावान छी। ऐ अल्लाह, मुहम्मद सल्लल्लाहु अलैहि वसल्लम आ मुहम्मदक परिवार पर बरकत दे जेना अहाँ इब्राहिम (अ. स.) आ इब्राहिमक परिवार पर बरकत देलहुँ; अहाँ प्रशंसनीय, महिमावान छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम पर प्रार्थना मे आ हर समय सलाम।", "जे एकटा बेर सलावत पठाबैत अछि, अल्लाह ओकरा दस दया पठा दैत अछि (मुसलमान 408)।"),
        "dua_wudu_after" to DuaText("वुडू के बाद", "हम गवाही दैत छी जे ककरो पूजा करबाक अधिकार नहि अछि सिवाय अल्लाह के, मात्र, बिना साझीदार, आ मुहम्मद सल्लल्लाहु अलैहि वसल्लम हुनकर दास आ रसूल छथि। ऐ अल्लाह, हमरा पश्चाताप करय वला आ पवित्र करय वला मे बना दियौक।", "वूडू पूरा करबाक बाद।", "स्वर्गक आठटा द्वार हुनका लेल खोलल जाइत अछि जे ओ जाहि मार्गसँ चाहियथि प्रवेश कऽ सकय।"),
        "dua_wudu_before" to DuaText("वुडूसँ पहिने", "अल्लाह के नाम पर।", "जखन वूडू शुरू होइत अछि।", "जे ओहि पर अल्लाहक नामक उल्लेख नहि करैत अछि, ओकर लेल कोनो (पूर्ण) वुडू नहि अछि।"),
        "dua_istiftah" to DuaText("आरम्भिक प्रार्थना (सना)", "महिमावान छी अहाँ, हे अल्लाह, आ प्रशंसा अहाँ पर होअय। अहाँक नाम धन्य अछि, अहाँक महिमा महान अछि, आ अहाँक अतिरिक्त कोनो देवता नहि अछि।", "नमाज़क प्रारम्भमे, उद्घाटन तकबीरक ठीक बाद।", "नमाज़क सुन्नत उद्घाटन दुआ।"),
        "dua_ruku" to DuaText("रुकू मे", "महिमावान हो हमर प्रभु, जे महान छथि।", "रुकूमे कमसँ कम तीन बेर।", "रुकुक सुन्नत तसबिह।"),
        "dua_sujood" to DuaText("सुजूदमे", "महिमावान हो हमर प्रभु, सर्वोच्च।", "कम सँ कम तीन बेर सुजूद मे।", "दास सजदा करैत काल अपन प्रभुक सबसँ निकट होइत अछि (मुसलमान 482)।"),
        "dua_rising_ruku" to DuaText("रुकू सँ उठैत", "अल्लाह ओहि व्यक्ति के सुनैत छथि जे हुनकर स्तुति करैत अछि। हमर प्रभु, समस्त प्रशंसा अहाँक अछि।", "रुकूसँ उठि सीधा ठाढ़ भऽ रहल अछि।", "जकर'रब्बाना वा लकल-हमद'स्वर्गदूत सभक पापक सङ्ग मेल खयैत अछि, ओकर पूर्व पाप क्षमा भऽ जाइत अछि।"),
        "dua_between_sajdas" to DuaText("दुनू सजदासक बीच", "हे हमर प्रभु, हमरा क्षमा करू।", "दुनू प्रणयक बीच बेसी रहैत।", "सजदा करबाक बीचमे बेसबाक सुन्नत दुआ।"),
        "dua_before_salam_four" to DuaText("चारि वस्तुक शरण (सलामसँ पहिने)", "ऐ अल्लाह, हम अहाँ मे नरकक सजा, कब्रक सजा, जीवन आ मृत्युक अज़माइश आ झूठा मसीहा (दज्जल) क अज़माइश के बुराई सँ शरण चाहैत छी।", "अंतिम ताशाहहुद आ सलावतक बाद, सलामक पहिने।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एहि चारि बात सँ शरण लेबाक आदेश देलनि।"),
        "dua_qunoot_witr" to DuaText("विटरमे कुनूट", "ऐ अल्लाह, अहाँ जिनका मार्ग देलहुँ, तकरा मे हमरा मार्गदर्शन करू, अहाँ जिनका कल्याण देलहुँ, हमरा तकरा मे कल्याण करू, हमरा ओहि मे लऽ लिअ जकरा अहाँ अपन देखभाल मे लग देलहुँ, जे किछु अहाँ देलहुँ ओकरा मे हमरा आशीर्वाद दियौक, आ जे किछु अहाँ देलहुँ ओकर अधलाह सँ हमरा बचा लिअ। अहाँ आदेश देलहुँ आ अहाँक विरुद्ध कोनो आदेश नहि देलहुँ, आ जकरा अहाँ सँ मित्रता करैत छी से कहियो अपमानित नहि होइत अछि। हमर प्रभु, अहाँ धन्य आ महान छी।", "विदर नमाज़मे-पैगम्बर सल्लल्लाहु अलैहि वसल्लम हसन इब्न अली (र.) केँ ई सिखौलनि।", "विदरक सुन्नत कुनूत (हनाफीसमे'अल्लाहुम्मा इन्ना नास्ताइनुका'सेहो प्रसिद्ध अछि।)"),
        "dua_qunoot_hanafi" to DuaText("कुनूत (अल्लाहुम्मा इन्ना नास्ताइनुका)", "ऐ अल्लाह, हम अहाँक सहायता आ क्षमा चाहैत छी, हम अहाँ पर विश्वास करैत छी आ अहाँ पर भरोसा करैत छी, हम सभ नीक तरीकासँ अहाँक प्रशंसा करैत छी, हम सभ अहाँक धन्यवाद करैत छी आ कृतघ्न नहि छी, आ जे केओ अहाँक आज्ञा नहि मानैत अछि ओकरा हम सभ छोड़ि दैत छी। हे अल्लाह, हम सभ केवल अहाँक पूजा करैत छी, हम सभ अहाँक पूजा करैत छी, हम सभ प्रार्थना करैत छी आ सिजदा करैत छी, हम सभ शीघ्रता करैत छी आ प्रयास करैत छी, हम सभ अहाँक दयाक आशा करैत छी आ अहाँक सँ दंडसँ डरैत छी, निश्चय ही अहाँक दंड इनकार करय वला सभ तक पहुँच जायत।", "विटरमे-हनाफीक अभ्यास।", "कुनूतमे उमर (र.) सँ रिपोर्ट कयल गेल।"),
        "dua_sleep_aslamtu" to DuaText("सोबासँ पहिने अन्तिम शब्दसभ", "ऐ अल्लाह, हम अपना केँ अहाँक अधीन करैत छी, हमर काज अहाँ केँ सौंपैत छी आ अहाँक आशा आ अहाँक भय सँ अपन सुरक्षा लेल अपन पीठ समर्पित करैत छी। अहाँक अतिरिक्त अहाँक कोनो आश्रय नहि अछि आ न बचबाक कोनो उपाय अछि। हम अहाँक पुस्तक पर विश्वास करैत छी जे अहाँ अवतरित कयलहुँ आ अहाँक पैगंबर पर जकरा अहाँ पठौलनि।", "वूडूक बाद, दाहिनी कात लेटब-सोबासँ पहिने अन्तिम शब्द।", "यदि ओहि राति हुनकर मृत्यु भऽ जाइत अछि तँ फित्राह (इस्लाम) पर हुनकर मृत्यु भऽ जाइत अछि।"),
        "dua_waking_night" to DuaText("राति मे जागब", "अल्लाह के अतिरिक्त ककरो पूजा करबाक अधिकार नहि अछि, केवल अल्लाह के बिना, बिना साझीदार। शासन हुनकर अछि आ प्रशंसा हुनकर अछि, आ ओ सब चीज पर शक्ति अछि। सब प्रशंसा अल्लाह के अछि, महिमा अल्लाह के अछि, अल्लाह के अलावा ककरो पूजा करबाक अधिकार नहि अछि, अल्लाह सबसँ महान छथि, आ अल्लाह के अलावा कोनो शक्ति या शक्ति नहि अछि। ऐ अल्लाह, हमरा क्षमा कऽ दियौक।", "राति मे जागय पर।", "हुनकर दुआक उत्तर देल जाइत अछि, आ जँ ओ वुडू करैत छथि आ प्रार्थना करैत छथि तँ हुनकर प्रार्थना स्वीकार कयल जाइत अछि।"),
        "dua_hamm_ibn_masud" to DuaText("दुखक दुआ (इब्न मसूद)", "ऐ अल्लाह, हम अहाँक दास छी, अहाँक दासक पुत्र छी, अहाँक दासीक पुत्र छी। हमर अग्र-ताला अहाँक हाथ मे अछि, अहाँ हमरा पर आदेश देलहुँ आ अहाँ हमरा पर न्यायपूर्ण आदेश देलहुँ। हम अहाँ सँ ओहि प्रत्येक नामक प्रार्थना करैत छी जाहि सँ अहाँ अपना नाम लेलनि, वा अपन पुस्तक मे प्रकट कयलहुँ, वा अहाँक कोनो सृष्टिकेँ सिखायल गेल, वा अदृश्यक ज्ञान मे अहाँ संग राखल गेल-कि अहाँ कुरान केँ हमर हृदयक झरना, हमर छातीक प्रकाश, हमर दुखक दूरी आ हमर चिन्ता के छोड़ि देलहुँ।", "दुख आ दुखमे-अल्लाह दुखक स्थान आनन्द लऽ लैत छथि।", "अल्लाह हुनकर चिन्ता आ दुखकेँ दूर करैत छथि आ हुनका ओकर स्थान पर आनन्द दैत छथि।"),
        "dua_difficulty_sahl" to DuaText("जखन किछु कठिन होइत अछि", "ऐ अल्लाह, किछु सेहो आसान नहि अछि सिवाय ओकर जे अहाँ सहज करैत छी, आ जँ अहाँ चाहैत छी तँ कठिनकेँ सरल करैत छी।", "जखन किछु कठिन अनुभव होइत अछि।", "परीक्षामे आसानी आ कठिन काज।"),
        "dua_musibah" to DuaText("एक आपदा पर (इस्तिरजा)", "अपना सभ अल्लाह के छी आ हम सभ ओही लग घुरब। ऐ अल्लाह, हमरा दुखक बदला दिअ आ हमरा लेल एकर बदला मे किछु बेहतर करू।", "कोनो हानि या आपदा पर।", "अल्लाह निश्चित रूपसँ किछु नीक दैत छथि-उम्म सलामह (रा) पैगम्बर सल्लल्लाहु अलैहि वसल्लम के देल गेल छल।"),
        "dua_debt" to DuaText("ऋणसँ राहत लेल", "ऐ अल्लाह, जे किछु अहाँ गैरकानूनी ठहराओलहुँ ओकर विरुद्ध अहाँ वैध कय देलहुँ से हमरा लेल पर्याप्त अछि, आ अपन अनुग्रहसँ हमरा अपन अतिरिक्त सभ सँ स्वतंत्र कऽ दियौक।", "ऋण चुकयबाक लेल-अली (आर. ए.) द्वारा सिखायल गेल।", "जँ ऋण पहाड़ जकाँ अछि तँ अल्लाह एकर समाधान कऽ देत।"),
        "dua_anger" to DuaText("जखन क्रोधित हो।", "हम शापित शयतान सँ अल्लाह मे शरण चाहैत छी।", "जखन क्रोधित हो।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि जे, \"जँ ओ ई कहैत छथि तँ हुनकर क्रोध दूर भऽ जायत।\""),
        "dua_waswasa" to DuaText("विश्वासमे वासवासाक विरुद्ध", "हम अल्लाह आ हुनकर रसूलसभ पर विश्वास करैत छी।", "जखन विश्वासक विषयमे शैतान फुसफुसबैत अछि तखन आबि जाइत अछि।", "जखन फुसफुस आबि जाय तखन ई कहि कऽ ओतऽ रोकि लिअ (आ अल्लाहमे शरण सेहो लऽ लिअ)।"),
    )
}
